'use client';

import { useEffect, useState } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import {
  ChartBarIcon,
  BuildingOfficeIcon,
  CubeIcon,
  BanknotesIcon,
  TrendingUpIcon,
  TrendingDownIcon,
  MagnifyingGlassIcon,
  FunnelIcon,
  ArrowPathIcon
} from '@heroicons/react/24/outline';
import { formatDate, formatCurrency, formatNumber } from '@/lib/utils';
import { api } from '@/lib/api';
import { DashboardSummaryResponse, BranchResponse, StockLevelResponse } from '@/types';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Card } from '@/components/ui/card';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

export default function DashboardReportsPage() {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [dashboardSummary, setDashboardSummary] = useState<DashboardSummaryResponse | null>(null);
  const [branches, setBranches] = useState<BranchResponse[]>([]);
  const [selectedBranch, setSelectedBranch] = useState<string>('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [refreshing, setRefreshing] = useState(false);

  const fetchData = async () => {
    try {
      setLoading(true);
      setError(null);

      const [summaryRes, branchesRes] = await Promise.all([
        api.dashboard.getSummary(),
        api.branches.getAll()
      ]);

      if (summaryRes.success && summaryRes.data) {
        setDashboardSummary(summaryRes.data);
      }

      if (branchesRes.success && branchesRes.data) {
        setBranches(branchesRes.data);
      }
    } catch (err: unknown) {
      console.error('Fetch dashboard reports error:', err);
      setError('Failed to load dashboard reports');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleRefresh = async () => {
    setRefreshing(true);
    await fetchData();
    setRefreshing(false);
  };

  const filteredBranchSummaries = dashboardSummary?.branchSummaries?.filter(branch =>
    branch.branchName.toLowerCase().includes(searchTerm.toLowerCase()) &&
    (selectedBranch === 'all' || branch.branchId === selectedBranch)
  ) || [];

  const totalInventoryValue = filteredBranchSummaries.reduce((sum, branch) => sum + branch.totalStockValue, 0);
  const totalProducts = filteredBranchSummaries.reduce((sum, branch) => sum + branch.totalProducts, 0);
  const totalUnits = filteredBranchSummaries.reduce((sum, branch) => sum + branch.totalUnits, 0);
  const totalLowStock = filteredBranchSummaries.reduce((sum, branch) => sum + branch.lowStockCount, 0);
  const totalOutOfStock = filteredBranchSummaries.reduce((sum, branch) => sum + branch.outOfStockCount, 0);

  if (loading) {
    return (
      <AuthGuard>
        <Layout>
          <div className="space-y-6">
            <div className="animate-pulse">
              <div className="h-8 bg-surface rounded w-1/3 mb-6"></div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {[...Array(4)].map((_, i) => (
                  <div key={i} className="card p-6">
                    <div className="h-4 bg-surface rounded w-2/3 mb-4"></div>
                    <div className="h-8 bg-surface rounded w-1/2"></div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </Layout>
      </AuthGuard>
    );
  }

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6">
          {/* Header */}
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
            <div>
              <h1 className="text-2xl font-bold text-primary">Dashboard Reports</h1>
              <p className="mt-1 text-sm text-text-secondary">
                Real-time inventory and performance metrics across all branches
              </p>
            </div>
            <Button onClick={handleRefresh} disabled={refreshing} className="gap-2">
              <ArrowPathIcon className={`h-4 w-4 ${refreshing ? 'animate-spin' : ''}`} />
              Refresh
            </Button>
          </div>

          {/* Error State */}
          {error && (
            <div className="bg-error-light border border-error/20 rounded-lg p-4">
              <p className="text-error text-sm">{error}</p>
            </div>
          )}

          {/* Summary Cards */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <Card className="p-6 border-l-4 border-success">
              <div className="flex items-center">
                <div className="p-3 bg-success/10 rounded-lg">
                  <BanknotesIcon className="h-6 w-6 text-success" />
                </div>
                <div className="ml-4">
                  <p className="text-xs font-bold text-text-secondary uppercase tracking-wider">Total Inventory Value</p>
                  <p className="text-2xl font-black text-success">{formatCurrency(totalInventoryValue)}</p>
                </div>
              </div>
            </Card>

            <Card className="p-6 border-l-4 border-primary">
              <div className="flex items-center">
                <div className="p-3 bg-primary/10 rounded-lg">
                  <CubeIcon className="h-6 w-6 text-primary" />
                </div>
                <div className="ml-4">
                  <p className="text-xs font-bold text-text-secondary uppercase tracking-wider">Total Products</p>
                  <p className="text-2xl font-black text-primary">{formatNumber(totalProducts)}</p>
                </div>
              </div>
            </Card>

            <Card className="p-6 border-l-4 border-info">
              <div className="flex items-center">
                <div className="p-3 bg-info/10 rounded-lg">
                  <ChartBarIcon className="h-6 w-6 text-info" />
                </div>
                <div className="ml-4">
                  <p className="text-xs font-bold text-text-secondary uppercase tracking-wider">Total Units</p>
                  <p className="text-2xl font-black text-info">{formatNumber(totalUnits)}</p>
                </div>
              </div>
            </Card>

            <Card className="p-6 border-l-4 border-warning">
              <div className="flex items-center">
                <div className="p-3 bg-warning/10 rounded-lg">
                  <TrendingDownIcon className="h-6 w-6 text-warning" />
                </div>
                <div className="ml-4">
                  <p className="text-xs font-bold text-text-secondary uppercase tracking-wider">Low Stock Items</p>
                  <p className="text-2xl font-black text-warning">{formatNumber(totalLowStock)}</p>
                </div>
              </div>
            </Card>
          </div>

          {/* Filters */}
          <Card className="p-4">
            <div className="flex flex-col sm:flex-row gap-4">
              <div className="flex-1">
                <div className="relative">
                  <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-text-secondary" />
                  <Input
                    placeholder="Search branches..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="!pl-10"
                  />
                </div>
              </div>
              <div className="sm:w-48">
                <Select value={selectedBranch} onValueChange={setSelectedBranch}>
                  <SelectTrigger>
                    <SelectValue placeholder="Filter by branch" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Branches</SelectItem>
                    {branches.map((branch) => (
                      <SelectItem key={branch.id} value={branch.id}>
                        {branch.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
          </Card>

          {/* Branch Details Table */}
          <Card className="p-6">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-lg font-bold text-primary">Branch Performance Summary</h2>
              <Badge variant="outline">
                {filteredBranchSummaries.length} branches
              </Badge>
            </div>

            {filteredBranchSummaries.length > 0 ? (
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead>
                    <tr className="border-b border-divider">
                      <th className="text-left py-3 px-4 text-xs font-black text-text-secondary uppercase tracking-wider">Branch</th>
                      <th className="text-left py-3 px-4 text-xs font-black text-text-secondary uppercase tracking-wider">Type</th>
                      <th className="text-right py-3 px-4 text-xs font-black text-text-secondary uppercase tracking-wider">Products</th>
                      <th className="text-right py-3 px-4 text-xs font-black text-text-secondary uppercase tracking-wider">Units</th>
                      <th className="text-right py-3 px-4 text-xs font-black text-text-secondary uppercase tracking-wider">Stock Value</th>
                      <th className="text-right py-3 px-4 text-xs font-black text-text-secondary uppercase tracking-wider">Low Stock</th>
                      <th className="text-right py-3 px-4 text-xs font-black text-text-secondary uppercase tracking-wider">Out of Stock</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-divider">
                    {filteredBranchSummaries.map((branch) => (
                      <tr key={branch.branchId} className="hover:bg-surface/50 transition-colors">
                        <td className="py-3 px-4">
                          <div className="flex items-center gap-3">
                            <div className="p-2 bg-primary/10 rounded-lg">
                              <BuildingOfficeIcon className="h-4 w-4 text-primary" />
                            </div>
                            <div>
                              <p className="font-bold text-primary">{branch.branchName}</p>
                            </div>
                          </div>
                        </td>
                        <td className="py-3 px-4">
                          <Badge variant={branch.branchType === 'WAREHOUSE' ? 'info' : 'default'}>
                            {branch.branchType === 'WAREHOUSE' ? 'Warehouse' : 'Shop'}
                          </Badge>
                        </td>
                        <td className="py-3 px-4 text-right font-medium">{formatNumber(branch.totalProducts)}</td>
                        <td className="py-3 px-4 text-right font-medium">{formatNumber(branch.totalUnits)}</td>
                        <td className="py-3 px-4 text-right font-bold text-success">{formatCurrency(branch.totalStockValue)}</td>
                        <td className="py-3 px-4 text-right">
                          <Badge variant={branch.lowStockCount > 0 ? 'warning' : 'success'}>
                            {formatNumber(branch.lowStockCount)}
                          </Badge>
                        </td>
                        <td className="py-3 px-4 text-right">
                          <Badge variant={branch.outOfStockCount > 0 ? 'error' : 'success'}>
                            {formatNumber(branch.outOfStockCount)}
                          </Badge>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="text-center py-12 text-text-secondary">
                <BuildingOfficeIcon className="h-12 w-12 mx-auto mb-4 opacity-20" />
                <p className="font-bold">No branches found</p>
                <p className="text-sm opacity-60">Try adjusting your search or filters</p>
              </div>
            )}
          </Card>
        </div>
      </Layout>
    </AuthGuard>
  );
}
